package com.ludomadagascar

import android.app.*
import android.os.Bundle
import android.graphics.*
import android.graphics.drawable.GradientDrawable
import android.text.InputType
import android.view.*
import android.widget.*
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL
import java.util.UUID
import kotlin.concurrent.thread

class MainActivity:Activity(){
 private val apiBase="http://10.0.2.2:3000"; private var token=""; private var userId=""; private var gameId=""; private var fee=0; private var version=0; private var state:JSONObject?=null
 private lateinit var root:LinearLayout; private lateinit var status:TextView
 private fun shape(c:Int,r:Float=28f)=GradientDrawable().apply{setColor(c);cornerRadius=r}
 private fun text(s:String,z:Float=16f,b:Boolean=false)=TextView(this).apply{text=s;textSize=z;setTextColor(Color.DKGRAY);setPadding(16,12,16,12);if(b)setTypeface(null,Typeface.BOLD)}
 private fun btn(s:String,c:Int=Color.rgb(45,95,190))=Button(this).apply{text=s;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);background=shape(c)}
 private fun page():LinearLayout{root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,28,24,22);setBackgroundColor(Color.rgb(247,249,252))};return root}
 private fun add(v:View,w:Int=-1,h:Int=-2){root.addView(v,LinearLayout.LayoutParams(w,h).apply{setMargins(0,8,0,8)})}
 override fun onCreate(b:Bundle?){super.onCreate(b);splash()}
 private fun splash(){page();root.gravity=Gravity.CENTER;add(text("🎲",64f,true));add(text("Ludo Madagascar",30f,true));add(text("Milalao • Mandresy • Mifaly"));add(ProgressBar(this),-2,-2);setContentView(root);root.postDelayed({login()},650)}
 private fun login(){page();add(text("Ludo Madagascar",29f,true));add(text("Midira na mamoròna kaonty"));status=text("");add(status);val u=EditText(this).apply{hint="Username";background=shape(Color.WHITE,18f)};val p=EditText(this).apply{hint="Password (10 caractères minimum)";inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_VARIATION_PASSWORD;background=shape(Color.WHITE,18f)};add(u);add(p);add(btn("HIDITRA")){setOnClickListener{auth("/api/auth/login",u.text.toString().trim(),p.text.toString())}};add(btn("HAMORONA KAONTY",Color.rgb(35,150,70))){setOnClickListener{auth("/api/auth/register",u.text.toString().trim(),p.text.toString())}};setContentView(root)}
 private fun auth(path:String,u:String,p:String){post(path,JSONObject().put("username",u).put("password",p)){j->token=j.optString("accessToken");userId=j.optJSONObject("user")?.optString("id").orEmpty();if(token.isBlank())status.text="Tsy tafiditra" else home()}}
 private fun home(){page();add(text("Tongasoa eto! 👋",29f,true));add(text("Ludo Madagascar"));status=text("Vonona hilalao ianao.");add(status);add(btn("🎮 HILALAO")){setOnClickListener{lobby()}};add(btn("💰 WALLET",Color.rgb(35,150,70))){setOnClickListener{wallet()}};add(btn("👤 PROFIL",Color.DKGRAY)){setOnClickListener{profile()}};setContentView(root)}
 private fun profile(){page();add(text("👤 Profil",29f,true));add(text("User ID: $userId",13f));add(btn("⌂ ACCUEIL")){setOnClickListener{home()}};setContentView(root)}
 private fun wallet(){page();add(text("💰 Wallet",29f,true));status=text("Loading...");add(status);add(btn("➕ DÉPÔT",Color.rgb(35,150,70))){setOnClickListener{pay(true)}};add(btn("➖ RETRAIT",Color.rgb(210,45,45))){setOnClickListener{pay(false)}};add(btn("↻ HAVAOZINA")){setOnClickListener{loadWallet()}};add(btn("⌂ ACCUEIL")){setOnClickListener{home()}};setContentView(root);loadWallet()}
 private fun loadWallet(){get("/api/wallet"){j->status.text="Balance: ${j.optLong("balance",j.optLong("balanceMGA",0))} Ar"}}
 private fun pay(dep:Boolean){val a=EditText(this).apply{hint="Montant Ar";inputType=InputType.TYPE_CLASS_NUMBER};val m=arrayOf("MVOLA","AIRTEL_MONEY","ORANGE_MONEY");AlertDialog.Builder(this).setTitle(if(dep)"Dépôt" else "Retrait").setSingleChoiceItems(m,0,null).setView(a).setPositiveButton("CONTINUER"){d,_->val x=a.text.toString().toLongOrNull()?:0;val i=(d as AlertDialog).listView.checkedItemPosition;if(x>0)post(if(dep)"/api/wallet/deposit" else "/api/wallet/withdraw",JSONObject().put("amountMGA",x).put("method",m[i]),UUID.randomUUID().toString()){loadWallet()}}.setNegativeButton("AOKA",null).show()}
 private fun lobby(){page();add(text("🎮 Safidio ny lalao",29f,true));status=text("");add(status);listOf(500 to Color.rgb(210,45,45),1000 to Color.rgb(45,95,190),2000 to Color.rgb(35,150,70)).forEach{(f,c)->add(btn("MILALAO — $f Ar",c)){setOnClickListener{create(f)}}};add(btn("HIDITRA AMIN'NY ROOM",Color.rgb(235,185,35))){setOnClickListener{joinDialog()}};add(btn("⌂ ACCUEIL")){setOnClickListener{home()}};setContentView(root)}
 private fun create(f:Int){fee=f;post("/api/games",JSONObject().put("entryFeeMGA",f),UUID.randomUUID().toString()){j->gameId=j.optString("gameId");if(gameId.isBlank())status.text="Game ID tsy hita" else room()}}
 private fun joinDialog(){val id=EditText(this).apply{hint="Game ID"};val f=EditText(this).apply{hint="Vola 500 / 1000 / 2000";inputType=InputType.TYPE_CLASS_NUMBER};val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;addView(id);addView(f)};AlertDialog.Builder(this).setTitle("Hiditra room").setView(box).setPositiveButton("HIDITRA"){_,_->val n=f.text.toString().toIntOrNull()?:0;if(id.text.isNotBlank()&&n in listOf(500,1000,2000)){gameId=id.text.toString();fee=n;post("/api/games/$gameId/join",JSONObject().put("entryFeeMGA",n),UUID.randomUUID().toString()){room()}}}.setNegativeButton("AOKA",null).show()}
 private fun room(){page();add(text("⏳ Room",29f,true));add(text("Mise: $fee Ar"));status=text("Miandry mpilalao...");add(status);add(text("Game ID: $gameId",12f));add(text("Mpilalao 4 no ilaina vao manomboka."));add(btn("↻ HAVAOZINA")){setOnClickListener{refreshLobby()}};add(btn("HIVERINA")){setOnClickListener{lobby()}};setContentView(root);refreshLobby();scheduleLobbyRefresh()}
 private fun scheduleLobbyRefresh(){root.postDelayed({if(this::root.isInitialized&&gameId.isNotBlank())refreshLobby()},3000)}
 private fun refreshLobby(){get("/api/games/$gameId/lobby"){j->val n=j.optJSONArray("participants")?.length()?:0;status.text="👥 Mpilalao: $n / 4";if(n>=2)refreshState() else scheduleLobbyRefresh()}}
 private fun board(){page();status=text("");add(status);add(text("🎲 LUDO MADAGASCAR",25f,true));val grid=GridLayout(this).apply{columnCount=15;rowCount=15;background=shape(Color.WHITE,24f);setPadding(4,4,4,4)};val cells=Array(15){arrayOfNulls<TextView>(15)};for(r in 0..14)for(c in 0..14){val x=TextView(this).apply{gravity=Gravity.CENTER;textSize=8f;background=shape(Color.WHITE,4f);layoutParams=GridLayout.LayoutParams().apply{width=0;height=0;rowSpec=GridLayout.spec(r,1f);columnSpec=GridLayout.spec(c,1f);setMargins(1,1,1,1)}};cells[r][c]=x;grid.addView(x)};root.addView(grid,LinearLayout.LayoutParams(-1,0,1f));add(btn("🎲 ROLL",Color.rgb(235,185,35))){setOnClickListener{roll()}});val row=LinearLayout(this);listOf(Color.rgb(210,45,45),Color.rgb(35,150,70),Color.rgb(235,185,35),Color.rgb(45,95,190)).forEachIndexed{i,c->row.addView(btn("P${i+1}",c){setOnClickListener{move(i)}},LinearLayout.LayoutParams(0,-2,1f))};add(row);setContentView(root);draw(cells);root.postDelayed({if(gameId.isNotBlank())refreshState()},5000)}
 private fun draw(c:Array<Array<TextView?>>){for(r in 0..14)for(x in 0..14){val on=(r==0&&x in 1..13)||(x==14&&r in 1..13)||(r==14&&x in 1..13)||(x==0&&r in 1..13);c[r][x]?.setBackgroundColor(if(on)Color.rgb(232,235,241)else Color.WHITE)};val ps=state?.optJSONArray("players")?:return;val cs=listOf(Color.RED,Color.rgb(35,150,70),Color.rgb(235,185,35),Color.rgb(45,95,190));for(pi in 0 until ps.length()){val ts=ps.optJSONObject(pi)?.optJSONArray("tokens")?:continue;for(ti in 0 until ts.length()){val pos=ts.optJSONObject(ti)?.optInt("pos",-1)?:-1;val q=if(pos<0)home(pi,ti)else path()[(pi*13+pos)%52];c[q.first][q.second]?.apply{text="●";textSize=16f;setTextColor(cs[pi]);setOnClickListener{if(pi==playerIndex())move(ti)}}}}}
 private fun refreshState(){get("/api/games/$gameId/state"){j->state=j;version=j.optInt("stateVersion",0);board();val i=j.optInt("currentPlayerIndex",0);status.text="Tour: ${listOf("🔴","🟢","🟡","🔵").getOrElse(i){"?"}} | Dice: ${j.optInt("dice",0)}"}}
 private fun playerIndex():Int{val a=state?.optJSONArray("players")?:return -1;for(i in 0 until a.length())if(a.optJSONObject(i)?.optString("id")==userId)return i;return -1}
 private fun roll(){post("/api/games/$gameId/roll",JSONObject().put("expectedVersion",version),UUID.randomUUID().toString()){refreshState()}}
 private fun move(i:Int){post("/api/games/$gameId/move",JSONObject().put("tokenIndex",i).put("expectedVersion",version),UUID.randomUUID().toString()){refreshState()}}
 private fun path():List<Pair<Int,Int>>{val p=mutableListOf<Pair<Int,Int>>();for(c in 1..13)p+=0 to c;for(r in 1..13)p+=r to 14;for(c in 13 downTo 1)p+=14 to c;for(r in 13 downTo 1)p+=r to 0;return p}
 private fun home(p:Int,t:Int)=when(p){0->listOf(2 to 2,2 to 4,4 to 2,4 to 4)[t];1->listOf(2 to 10,2 to 12,4 to 10,4 to 12)[t];2->listOf(10 to 2,10 to 4,12 to 2,12 to 4)[t];else->listOf(10 to 10,10 to 12,12 to 10,12 to 12)[t]}
 private fun get(p:String,ok:(JSONObject)->Unit)=request("GET",p,null,null,ok)
 private fun post(p:String,b:JSONObject,id:String?=null,ok:(JSONObject)->Unit)=request("POST",p,b,id,ok)
 private fun request(m:String,p:String,b:JSONObject?,id:String?,ok:(JSONObject)->Unit){if(::status.isInitialized)status.text="Miandry...";thread{try{val c=(URL(apiBase+p).openConnection() as HttpURLConnection).apply{requestMethod=m;setRequestProperty("Content-Type","application/json");if(token.isNotBlank())setRequestProperty("Authorization","Bearer $token");if(!id.isNullOrBlank())setRequestProperty("Idempotency-Key",id);connectTimeout=10000;readTimeout=10000;doInput=true;if(b!=null)doOutput=true};if(b!=null)c.outputStream.use{it.write(b.toString().toByteArray())};val code=c.responseCode;val tx=(if(code in 200..299)c.inputStream else c.errorStream)?.bufferedReader()?.readText().orEmpty();if(code !in 200..299){val msg=try{JSONObject(tx).optString("error","Erreur HTTP $code")}catch(_:Exception){"Erreur HTTP $code"};runOnUiThread{status.text=msg};return@thread};runOnUiThread{ok(if(tx.isBlank())JSONObject()else JSONObject(tx))}}catch(e:Exception){runOnUiThread{status.text="Erreur réseau: ${e.message ?: e.javaClass.simpleName}"}}}}
}
